#!/usr/bin/env node
// Publishes the packages whose current version is not on npm yet, then tags the release.
//
//   node scripts/release.mjs --check     prints pending=true|false (for GitHub outputs) and exits
//   node scripts/release.mjs             packs, publishes, writes release/manifest.json, tags vX.Y.Z and vX
//   node scripts/release.mjs --dry-run   packs and writes the manifest, publishes and tags nothing
//
// Publishing uses npm trusted publishing (OIDC, provenance generated by npm) when the workflow has
// `id-token: write`, or NODE_AUTH_TOKEN when it is set. Tarballs come from `pnpm pack`, which replaces
// workspace:* ranges with real versions and produces byte-reproducible archives (see release-verify.mjs).
import { execFileSync, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { appendFileSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
/** Publish order: dependencies first. */
export const PACKAGES = ['core', 'openapi', 'engine', 'reporters', 'app', 'cli'];
const args = new Set(process.argv.slice(2));
const win = process.platform === 'win32';

const pkgOf = (dir) => JSON.parse(readFileSync(join(root, 'packages', dir, 'package.json'), 'utf8'));
const run = (cmd, argv, opts = {}) => spawnSync(cmd, argv, { encoding: 'utf8', shell: win, ...opts });

function published(name, version) {
  const r = run('npm', ['view', `${name}@${version}`, 'version'], { cwd: root });
  return r.status === 0 && r.stdout.trim() === version;
}

const packages = PACKAGES.map((dir) => ({ dir, ...pkgOf(dir) }));
const version = packages[0].version;
if (packages.some((p) => p.version !== version)) {
  console.error(`Packages are not in lockstep: ${packages.map((p) => `${p.name}@${p.version}`).join(', ')}`);
  process.exit(1);
}
// Publish only released versions: after the Version Packages PR is merged no changeset files remain, and the
// version is not the 0.0.0 placeholder. Otherwise every push to main would try to publish the current version.
const changesets = readdirSync(join(root, '.changeset')).filter((f) => f.endsWith('.md') && f !== 'README.md');
const releasable = changesets.length === 0 && version !== '0.0.0';
const pending = releasable ? packages.filter((p) => !published(p.name, p.version)) : [];
if (!releasable)
  console.error(
    `Not releasable: ${changesets.length > 0 ? `${String(changesets.length)} pending changeset(s)` : 'version 0.0.0'}.`,
  );

if (args.has('--check')) {
  const line = `pending=${String(pending.length > 0)}\nversion=${version}\n`;
  if (process.env.GITHUB_OUTPUT) appendFileSync(process.env.GITHUB_OUTPUT, line);
  process.stdout.write(line);
  process.exit(0);
}

if (pending.length === 0 && !args.has('--dry-run')) {
  console.log(`Nothing to publish (${version}).`);
  process.exit(0);
}

const out = join(root, 'release');
mkdirSync(out, { recursive: true });
const manifest = { version, packages: [] };
for (const p of packages) {
  const before = new Set(readdirSync(out));
  const r = run('pnpm', ['pack', '--pack-destination', out], { cwd: join(root, 'packages', p.dir) });
  if (r.status !== 0) throw new Error(`pnpm pack failed for ${p.name}\n${r.stderr}`);
  const file = readdirSync(out).find((f) => !before.has(f) && f.endsWith('.tgz'));
  const sha256 = createHash('sha256')
    .update(readFileSync(join(out, file)))
    .digest('hex');
  manifest.packages.push({ name: p.name, version: p.version, file, sha256 });
  console.log(`${p.name}@${p.version}  ${sha256}`);
}
writeFileSync(join(out, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);

if (args.has('--dry-run')) {
  console.log('Dry run: nothing published or tagged.');
  process.exit(0);
}

for (const m of manifest.packages) {
  if (!pending.some((p) => p.name === m.name)) {
    console.log(`skip ${m.name}@${m.version} (already published)`);
    continue;
  }
  const tag = version.includes('-') ? ['--tag', 'next'] : [];
  const r = run('npm', ['publish', join(out, m.file), '--access', 'public', '--provenance', ...tag], {
    cwd: root,
    stdio: 'inherit',
  });
  if (r.status !== 0) throw new Error(`npm publish failed for ${m.name}@${m.version}`);
}

// Tags: vX.Y.Z for the release, and the moving major tag the GitHub Action is used with (uses: …@v1).
const git = (...a) => execFileSync('git', a, { cwd: root, encoding: 'utf8' }).trim();
const major = `v${version.split('.')[0]}`;
git('tag', '-a', `v${version}`, '-m', `ContractGuard ${version}`);
if (!version.includes('-')) git('tag', '-f', '-a', major, '-m', `ContractGuard ${version}`);
git('push', 'origin', `v${version}`);
if (!version.includes('-')) git('push', '-f', 'origin', major);
console.log(`Published and tagged v${version}${version.includes('-') ? '' : ` (${major} moved)`}.`);
